	var document map[string]json.RawMessage
	if err := json.Unmarshal([]byte(raw), &document); err != nil {
		return nil, fmt.Errorf("schema must be a JSON object: %w", err)
	}
	if document == nil {
		return nil, errors.New("schema must be a JSON object")
	}

